namespace RonSijm.FluidHumidifier.Factories.Wisdom;

public class AIGuardrailFactory(string resourceName = null, Action<Humidifier.Wisdom.AIGuardrail> factoryAction = null) : ResourceFactory<Humidifier.Wisdom.AIGuardrail>(resourceName)
{

    internal InnerAIGuardrailAIGuardrailTopicPolicyConfigFactory TopicPolicyConfigFactory { get; set; }

    internal InnerAIGuardrailAIGuardrailWordPolicyConfigFactory WordPolicyConfigFactory { get; set; }

    internal InnerAIGuardrailAIGuardrailContextualGroundingPolicyConfigFactory ContextualGroundingPolicyConfigFactory { get; set; }

    internal InnerAIGuardrailAIGuardrailSensitiveInformationPolicyConfigFactory SensitiveInformationPolicyConfigFactory { get; set; }

    internal InnerAIGuardrailAIGuardrailContentPolicyConfigFactory ContentPolicyConfigFactory { get; set; }

    protected override Humidifier.Wisdom.AIGuardrail Create()
    {
        var aIGuardrailResult = CreateAIGuardrail();
        factoryAction?.Invoke(aIGuardrailResult);

        return aIGuardrailResult;
    }

    private Humidifier.Wisdom.AIGuardrail CreateAIGuardrail()
    {
        var aIGuardrailResult = new Humidifier.Wisdom.AIGuardrail
        {
            GivenName = InputResourceName,
        };

        return aIGuardrailResult;
    }
    public override void CreateChildren(Humidifier.Wisdom.AIGuardrail result)
    {
        base.CreateChildren(result);

        result.TopicPolicyConfig ??= TopicPolicyConfigFactory?.Build();
        result.WordPolicyConfig ??= WordPolicyConfigFactory?.Build();
        result.ContextualGroundingPolicyConfig ??= ContextualGroundingPolicyConfigFactory?.Build();
        result.SensitiveInformationPolicyConfig ??= SensitiveInformationPolicyConfigFactory?.Build();
        result.ContentPolicyConfig ??= ContentPolicyConfigFactory?.Build();
    }

} // End Of Class

